-- Insert wards for ABA NORTH, ABIA
INSERT INTO nigerian_wards (area_id, name)
SELECT id, ward FROM (
  SELECT na.id FROM nigerian_areas na
  JOIN nigerian_states ns ON na.state_id = ns.id
  WHERE ns.name = 'ABIA' AND na.name = 'ABA NORTH'
) a
CROSS JOIN (
  VALUES
    ('ARIARIA MARKET'),
    ('EZIAMA'),
    ('INDUSTRIAL AREA'),
    ('OGBOR I'),
    ('OGBOR II'),
    ('OLD GRA'),
    ('OSUSU I'),
    ('OSUSU II'),
    ('ST. EUGENE'),
    ('UMUOGOR'),
    ('UMUOLA'),
    ('URATTA')
) AS w(ward);

