  SELECT na.id FROM nigerian_areas na
  JOIN nigerian_states ns ON na.state_id = ns.id
  WHERE ns.name = 'ENUGU' AND na.name = 'ENUGU NORTH'
) a
CROSS JOIN (
  VALUES
    ('ASATA TOWNSHIP'),
    ('CHINA TOWN'),
    ('GRA'),
    ('IHEWUZI'),
    ('INDEPENDENCE LAYOUT'),
    ('NEW HAVEN'),
    ('OGBETE EAST'),
    ('OGBETE WEST'),
    ('OGUI NEW LAYOUT'),
    ('OGUI TOWNSHIP'),
    ('ONU-ASATA'),
    ('UDI SIDING/ IVA VALLEY'),
    ('UMUNEVO')
) AS w(ward);

