  SELECT id FROM nigerian_states WHERE name = 'IMO'
) s
CROSS JOIN (
  VALUES
    ('ABOH MBAISE'),
    ('EHIME MBANO'),
    ('EZINHITTE MBAISE'),
    ('IDEATO NORTH'),
    ('IDEATOR SOUTH'),
    ('IHITTE UBOMA'),
    ('IKEDURU'),
    ('ISIALA MBANO'),
    ('ISU'),
    ('MBAISE'),
    ('MBAITOLI'),
    ('NGOR OKPALA'),
    ('NJABA'),
    ('NKWERRE'),
    ('NWANGELE'),
    ('OBOWO'),
    ('OGUTA'),
    ('OHAJI/EGBEME'),
    ('OKIGWE'),
    ('ONUIMO'),
    ('ORLU'),
    ('ORSU'),
    ('ORU EAST'),
    ('ORU WEST'),
    ('OWERRI MUNICIPAL'),
    ('OWERRI NORTH'),
    ('OWERRI WEST')
) AS l(lga);

-- Insert wards for ABOH MBAISE, IMO
INSERT INTO nigerian_wards (area_id, name)
SELECT id, ward FROM (
  SELECT na.id FROM nigerian_areas na
  JOIN nigerian_states ns ON na.state_id = ns.id
  WHERE ns.name = 'IMO' AND na.name = 'ABOH MBAISE'
